// Testbench (#186): ft710_scope_spi (behavioural) on its own, and with -DSTRUCT against the netlist slice of the
// scope serializer.
//
// Without STRUCT it runs the RTL only (no derived files): decodes the frames on spi_cs_n / spi_clk / spi_dat
// (falling-edge sampling, MSB first) and checks length 1,700 bytes, period 614,400 clocks, bytes 0..849 = the RAM
// bank being read (ping-pong per frame), bytes 850..1699 = 0xCC, and the ramp test mode.
// With -DSTRUCT it also instantiates `ft710_slice` from build/sdr/sim/scope_ser.v, generated by
//   python3 -I tools/xc7_netlist_verilog.py slice build/sdr/netlist.json build/sdr/sim/scope_ser.v \
//     --seeds SLICE_X12Y48/AFF,SLICE_X5Y50/AFF,SLICE_X12Y49/AFF,SLICE_X15Y49/AFF,SLICE_X58Y49/AFF,SLICE_X58Y49/BFF,SLICE_X58Y49/B5FF,SLICE_X58Y49/CFF,SLICE_X58Y49/A5FF,SLICE_X58Y50/CFF,SLICE_X58Y50/AFF,SLICE_X58Y50/A5FF,SLICE_X58Y50/BFF,SLICE_X34Y53/AFF \
//     --depth 12 --stop RAMB18_X2Y21,SLICE_X28Y73/A5FF,SLICE_X40Y60/BFF,SLICE_X1Y47/AFF
// feeds both the same RAM model, enable, reset and ramp inputs, and compares the three pins and the read address
// on every clock. Usage: hdl/sdr/README.md.
`timescale 1ns/1ps
`default_nettype none
module tb_scope_spi;
  reg clk = 1'b0;
  always #5 clk = ~clk;
  reg rst = 1'b1, en = 1'b0, ramp = 1'b0;

  // RAMB18_X2Y21 port B stand-in: x9 read, DOB_REG = 1 (data two clocks after the address)
  reg [7:0] mem [0:2047];
  integer i;
  initial for (i = 0; i < 2048; i = i + 1) mem[i] = (i * 37 + (i >> 10) * 101 + 11) & 8'hFF;

  wire [10:0] addr;
  wire sclk, cs_n, dat;
  reg  [7:0] d1, d2;
  always @(posedge clk) begin d1 <= mem[addr]; d2 <= d1; end
  ft710_scope_spi dut (.clk(clk), .rst(rst), .en(en), .ramp(ramp), .rd_addr(addr), .rd_data(d2),
                       .spi_clk(sclk), .spi_cs_n(cs_n), .spi_dat(dat));

  integer errors = 0, cyc = 0;
`ifdef STRUCT
  wire [10:0] sa;
  wire ssclk, scs_n, sdat;
  reg  [7:0] s1, s2;
  always @(posedge clk) begin s1 <= mem[sa]; s2 <= s1; end
  ft710_slice s (
    .i_RAMB18_X2Y21_DOBDO0(s2[0]), .i_RAMB18_X2Y21_DOBDO1(s2[1]), .i_RAMB18_X2Y21_DOBDO2(s2[2]),
    .i_RAMB18_X2Y21_DOBDO3(s2[3]), .i_RAMB18_X2Y21_DOBDO4(s2[4]), .i_RAMB18_X2Y21_DOBDO5(s2[5]),
    .i_RAMB18_X2Y21_DOBDO6(s2[6]), .i_RAMB18_X2Y21_DOBDO7(s2[7]),
    .i_SLICE_X40Y60_BFF_Q(ramp), .i_SLICE_X1Y47_AFF_Q(rst), .i_SLICE_X28Y73_A5FF_Q(en),
    .i_BUFHCE_X0Y9_O(clk), .i_BUFHCE_X1Y20_O(clk), .i_BUFHCE_X0Y21_O(clk), .i_BUFHCE_X1Y8_O(clk),
    .o_SLICE_X12Y48_AFF_Q(sdat), .o_SLICE_X12Y49_AFF_Q(ssclk), .o_SLICE_X5Y50_AFF_Q(scs_n),
    .o_SLICE_X15Y49_AFF_Q(sa[0]), .o_SLICE_X58Y49_AFF_Q(sa[1]), .o_SLICE_X58Y49_BFF_Q(sa[2]),
    .o_SLICE_X58Y49_B5FF_Q(sa[3]), .o_SLICE_X58Y49_CFF_Q(sa[4]), .o_SLICE_X58Y49_A5FF_Q(sa[5]),
    .o_SLICE_X58Y50_CFF_Q(sa[6]), .o_SLICE_X58Y50_AFF_Q(sa[7]), .o_SLICE_X58Y50_A5FF_Q(sa[8]),
    .o_SLICE_X58Y50_BFF_Q(sa[9]), .o_SLICE_X34Y53_AFF_Q(sa[10]));
  integer mism = 0;
  always @(negedge clk)
    if ({sdat, ssclk, scs_n, sa} !== {dat, sclk, cs_n, addr}) begin
      if (mism < 20) $display("MISMATCH cyc %0d: slice dat %b clk %b cs_n %b a %0d | rtl %b %b %b %0d",
                              cyc, sdat, ssclk, scs_n, sa, dat, sclk, cs_n, addr);
      mism = mism + 1;
    end
`endif

  // frame decoder on the RTL pins
  reg pclk = 1, pcs = 1;
  integer nbits = 0, fstart = 0, lastfs = -1, frames = 0, k;
  reg [7:0] cur;
  reg [7:0] fr [0:2047];
  reg       framebank;
  always @(posedge clk) begin
    cyc <= cyc + 1;
    if (pcs && !cs_n) begin nbits = 0; fstart = cyc; framebank = addr[10]; end
    if (!cs_n && pclk && !sclk) begin
      cur = {cur[6:0], dat}; nbits = nbits + 1;
      if (nbits % 8 == 0) fr[nbits / 8 - 1] = cur;
    end
    if (!pcs && cs_n) begin
      frames = frames + 1;
      if (nbits != 13600) begin errors = errors + 1; $display("FAIL frame %0d: %0d bits", frames, nbits); end
      if (lastfs >= 0 && fstart - lastfs != 614400) begin
        errors = errors + 1; $display("FAIL frame %0d: period %0d", frames, fstart - lastfs);
      end
      for (k = 0; k < 1700; k = k + 1)
        if (fr[k] !== (k >= 850 ? 8'hCC : ramp ? k[7:0] : mem[{framebank, k[9:0]}])) begin
          if (errors < 10) $display("FAIL frame %0d byte %0d = %02X", frames, k, fr[k]);
          errors = errors + 1;
        end
      $display("frame %0d: start %0d, %0d bytes, bank %0d, bytes 0..3 %02X %02X %02X %02X, 849 %02X, 850 %02X",
               frames, fstart, nbits / 8, framebank, fr[0], fr[1], fr[2], fr[3], fr[849], fr[850]);
      lastfs = fstart;
    end
    pclk = sclk; pcs = cs_n;
  end

  initial begin
    repeat (20) @(posedge clk); rst <= 1'b0;
    repeat (20) @(posedge clk); en <= 1'b1;
    wait (frames == 3);
    @(posedge clk); ramp <= 1'b1;             // switched between frames
    wait (frames == 4);
    repeat (1000) @(posedge clk); en <= 1'b0; lastfs = -1; // disable mid-gap: all three lines idle high
    repeat (5) @(posedge clk);
    if ({sclk, cs_n, dat} !== 3'b111) begin errors = errors + 1; $display("FAIL: lines not idle high after en = 0"); end
    repeat (100) @(posedge clk); en <= 1'b1;
    wait (frames == 5);
`ifdef STRUCT
    $display("slice comparison: %0d mismatching clocks", mism);
    if (mism) errors = errors + 1;
`endif
    $display("%s (%0d errors)", errors ? "FAIL" : "PASS", errors);
    $finish;
  end
endmodule
`default_nettype wire
